"""Partition one existing separator opening between four original mouth corners.

A member may traverse several corridor/patch owners. The four terminal mouth
indices and per-side owner permissions are prepared from the original network;
this node group never chooses a city block by area, proximity or elevation.
It copies existing edges and vertices only. Production dispatch must validate
the declarations against the original route chains before calling this group.
"""
import bpy
from . import curved_separator_boundary_nodes as simple
from . import curved_patch_provider_nodes as providers
from . import curved_network_ownership_nodes as ownership

c = simple.c
NAME = 'Prochitecture Streets / Chained separator boundary v1'
MAX_OWNER_RULES = 512
PORTS = ('A Head', 'A Tail', 'B Head', 'B Tail')
PIECES = ('Side A', 'Side B', 'Head', 'Tail')


def _path(g, wire, anchor_ids, first, last):
    """Cut the other two corners, then select the unique path between these.

    Unit edge costs make both distance fields integer-valued. Once the closed
    degree-two wire is cut, the path cannot choose the other side of its cycle.
    Disconnected/opposite terminals fail instead of inventing a connection.
    """
    own = c.named(g, 'st_sb_original_vertex', 'INT')
    other = [i for i in range(4) if i not in (first, last)]
    excluded = sum(g.math('COMPARE', own, anchor_ids[i]) for i in other)
    cut = c._select(g, wire, 1.-excluded)
    for i, terminal in enumerate((first, last)):
        path = g.node('GeometryNodeInputShortestEdgePaths', 'Unit costs along the existing cut wire')
        path.inputs['Edge Cost'].default_value = 1.
        g.bind(g.math('COMPARE', own, anchor_ids[terminal]), path.inputs['End Vertex'])
        cut = c._store(g, cut, '_sr_distance_'+str(i), path.outputs['Total Cost'], 'FLOAT')
    da, db = (c.named(g, '_sr_distance_'+str(i), 'FLOAT') for i in range(2))
    end = g.math('COMPARE', own, anchor_ids[last])
    distance = c._stat(g, cut, c.choose(g, end, da, 0.), 'Max')
    count = c._count(g, wire)
    finite = g.math('LESS_THAN', da, count)*g.math('LESS_THAN', db, count)
    selected = finite*g.math('COMPARE', da+db, distance)
    part = c._select(g, cut, selected)
    valid = g.math('GREATER_THAN', distance, .5)*g.math('LESS_THAN', distance, count)
    return part, valid


def build(*, capture_wire=False):
    name=NAME+(' / Captured wire tags' if capture_wire else '')
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    g = c.Graph(name)
    for name in ('Pavement', 'Mouths', 'Allowed Owners'):
        g.socket(name, 'NodeSocketGeometry')
    for name in PORTS:
        g.socket(name, 'NodeSocketInt')
    for name in ('Boundary', *PIECES, 'Diagnostics'):
        g.socket(name, 'NodeSocketGeometry', 'OUTPUT')
    g.socket('Valid', 'NodeSocketBool', 'OUTPUT')
    inp = g.node('NodeGroupInput'); out = g.node('NodeGroupOutput')
    index = c.V(g, g.node('GeometryNodeInputIndex').outputs[0])
    if capture_wire:
        wire=simple.captured_wire(g,inp.outputs['Pavement'],original_edge=True)
    else:
        pavement = c._store(g, inp.outputs['Pavement'], 'st_sb_original_vertex', index, 'INT')
        for name in ('kind', 'owner'):
            pavement = g.store(pavement, 'st_sb_'+name, c.named(g, 'st_cn_'+name, 'INT'), 'EDGE', 'INT')
        pavement = g.store(pavement, 'st_sr_original_edge', index, 'EDGE', 'INT')
        uses = g.node('GeometryNodeInputMeshEdgeNeighbors')
        wire = simple._edges(g, pavement, g.math('COMPARE', uses.outputs['Face Count'], 1.))
    islands = g.node('GeometryNodeInputMeshIsland')
    neighbors = g.node('GeometryNodeInputMeshVertexNeighbors')
    keys = g.separate(c.named(g, '_bridge_key', 'FLOAT_VECTOR'))
    anchors = []; chosen_island = None; valid = 1.; metrics = {}
    for i, name in enumerate(PORTS):
        port = inp.outputs[name]
        found, row = providers._lookup(g, inp.outputs['Mouths'], 'st_cj_input_index', port)
        half = c._read(g, inp.outputs['Mouths'], 'st_cj_half', row, 'INT')
        rank = .5*(half+1.)*c._read(g, inp.outputs['Mouths'], 'st_cs_intervals', row, 'INT')
        anchor = g.math('COMPARE', keys[0], 0.)*g.math('COMPARE', keys[1], port)*g.math('COMPARE', keys[2], rank)
        count = c._stat(g, wire, anchor, 'Sum')
        island = c._stat(g, wire, anchor*c.V(g, islands.outputs['Island Index']), 'Sum')
        original = c._stat(g, wire, anchor*c.named(g, 'st_sb_original_vertex', 'INT'), 'Sum')
        valid = valid*found*g.math('COMPARE', count, 1.)*g.math('COMPARE', g.math('ABSOLUTE', half), 1.)
        if chosen_island is None:
            chosen_island = island
        else:
            valid = valid*g.math('COMPARE', chosen_island, island)
        for previous in anchors:
            valid = valid*(1.-g.math('COMPARE', previous, original))
        anchors.append(original); metrics['anchor_'+str(i)+'_count'] = count
    wire = c._select(g, wire, g.math('COMPARE', islands.outputs['Island Index'], chosen_island))
    valid = valid*c._stat(g, wire, g.math('COMPARE', neighbors.outputs['Vertex Count'], 2.))
    valid = valid*g.math('GREATER_THAN', c._count(g, wire), 3.5)

    rules = inp.outputs['Allowed Owners']
    role = c.named(g, 'st_sr_role', 'INT'); kind = c.named(g, 'st_sr_kind', 'INT'); owner = c.named(g, 'st_sr_owner', 'INT')
    valid = valid*c._stat(g, rules, ownership._exists(g, ('st_sr_role','st_sr_kind','st_sr_owner')))
    valid = valid*g.math('GREATER_THAN', c._count(g, rules), .5)
    valid = valid*(1.-g.math('GREATER_THAN', c._count(g, rules), MAX_OWNER_RULES))
    domain_ok = (1.-g.math('LESS_THAN', role, 0.))*g.math('LESS_THAN', role, 4.)
    domain_ok = domain_ok*g.math('MAXIMUM', g.math('COMPARE', kind, 0.), g.math('COMPARE', kind, 1.))
    domain_ok = domain_ok*(1.-g.math('LESS_THAN', owner, 0.))*g.math('LESS_THAN', owner, 2**20)
    valid = valid*c._stat(g, rules, domain_ok)
    # These are small local owner indices, never OSM or original Street IDs.
    rules = g.setpos(rules, g.xyz(role,kind,owner))
    merge = g.node('GeometryNodeMergeByDistance', 'Owner permission rows must be unique')
    merge.inputs['Distance'].default_value = .1
    g.bind(rules, merge.inputs['Geometry'])
    valid = valid*g.math('COMPARE', c._count(g, rules), c._count(g, merge.outputs['Geometry']))
    pieces = {}; tagged = []
    for r, (name, endpoints) in enumerate(zip(PIECES, ((0,1),(2,3),(0,2),(1,3)))):
        part, connected = _path(g, wire, anchors, *endpoints)
        requested = g.xyz(float(r), c.named(g,'st_sb_kind','INT'), c.named(g,'st_sb_owner','INT'))
        lookup = g.node('GeometryNodeSampleNearest', 'Only owners declared for this exact boundary side')
        lookup.domain = 'POINT'
        g.bind(rules, lookup.inputs['Geometry']); g.bind(requested, lookup.inputs['Sample Position'])
        actual = c._sample(g, rules, g.position(), lookup.outputs['Index'], 'FLOAT_VECTOR')
        distance = g.node('ShaderNodeVectorMath', 'Exact small integer owner permission'); distance.operation = 'DISTANCE'
        g.bind(requested, distance.inputs[0]); g.bind(actual, distance.inputs[1])
        allowed = g.math('LESS_THAN', distance.outputs['Value'], .1)
        ends = g.math('COMPARE', neighbors.outputs['Vertex Count'], 1.)
        degree = g.math('MAXIMUM', ends, g.math('COMPARE', neighbors.outputs['Vertex Count'], 2.))
        valid = valid*connected*c._stat(g, part, allowed, domain='EDGE')
        valid = valid*c._stat(g, part, degree)*g.math('COMPARE', c._stat(g, part, ends, 'Sum'), 2.)
        valid = valid*g.math('COMPARE', c._stat(g, part, islands.outputs['Island Count'], 'Max'), 1.)
        pieces[name] = part; tagged.append(part)
        metrics['side_'+str(r)+'_vertices'] = c._count(g, part)
    joined = simple.boundary._join(g, *tagged)
    once = g.node('GeometryNodeAccumulateField', 'Each original boundary edge is used exactly once')
    once.data_type = 'INT'; once.domain = 'EDGE'; once.inputs['Value'].default_value = 1
    g.bind(c.named(g, 'st_sr_original_edge', 'INT'), once.inputs['Group ID'])
    valid = valid*c._stat(g, joined, g.math('COMPARE', once.outputs['Total'], 1.), domain='EDGE')
    sizes = []
    for mesh in (joined, wire):
        size = g.node('GeometryNodeAttributeDomainSize'); size.component = 'MESH'
        g.bind(mesh, size.inputs['Geometry']); sizes.append(size.outputs['Edge Count'])
    valid = valid*g.math('COMPARE', *sizes)
    record = c._line(g, 1)
    for name, value in metrics.items():
        record = c._store(g, record, 'st_sb_'+name, value, 'INT')
    record = c._store(g, record, 'st_sb_valid', valid, 'BOOLEAN')
    for name, mesh in dict(Boundary=wire, **pieces).items():
        g.bind(simple.boundary._empty(g, mesh, valid), out.inputs[name])
    g.bind(record, out.inputs['Diagnostics']); g.bind(valid, out.inputs['Valid'])
    return g.g
